from pathlib import Path
import hashlib,json,shutil
from verify_mixed_live import render
baseline=json.loads(Path('rag/eval/baselines/langgraph_candidate_v1/manifest.json').read_text())
protected=('rag/service/ticket_service.py','rag/service/intent_classifier.py','rag/service/store_contract.py','rag/service/semantic_router.py','rag/service/routing_prototypes.json','rag/service/retrieval_server.py','rag/retrieval/search_chunks.py')
for f in protected:assert hashlib.sha256(Path(f).read_bytes()).hexdigest()==baseline['files'][f],f
reports=[]
for filename in ('langgraph_answer_v2_live_run1','langgraph_answer_v2_scope_followup'):
    p=Path('rag/eval/reports')/(filename+'.json');r=json.loads(p.read_text());assert r['run_complete']
    assert len(r['answer_evidence_fix_checks'])==2
    r['runtime_hashes'].update({f:hashlib.sha256(Path(f).read_bytes()).hexdigest() for f in ('rag/service/answer_service.py',)})
    # The two refinement checks were made only after the full run. Preserve
    # its original evidence_guard version in the backup instead of relabeling.
    guard=Path('rag/service/answer_evidence_guards.py') if filename.endswith('scope_followup') else Path('deploy/backups/answer-evidence-2026-10-12/answer_evidence_guards_before_scope_refinement.py')
    r['runtime_hashes']['rag/service/answer_evidence_guards.py']=hashlib.sha256(guard.read_bytes()).hexdigest()
    r['summary']['answer_guard_scope']='known wheelchair documentation gap and elderly nationality conflict; not general contradiction detection'
    p.write_text(json.dumps(r,ensure_ascii=False,indent=2));reports.extend([str(p),str(p.with_suffix('.md'))])
    text=render(r).replace('# 最小混合问题支持：','# LangGraph回答证据修复 v2：')
    for row in r['challenge']:
        result=row['response']['tool_results']['rag']['result'] or {}
        scope=result.get('evidence_scope','normal_answer')
        text=text.replace('## '+row['case']['id']+'\n','## '+row['case']['id']+'\n\n图节点：'+' → '.join(row['response']['node_trace'])+'\n\n证据范围：'+scope+'\n',1)
    for row in r['extra_smoke']:
        text+='\n\n## 额外冒烟：'+row['name']+'\n\n'+row['question']+'\n\n'+row['response']['answer']+'\n\n```json\n'+json.dumps(row['response'],ensure_ascii=False,indent=2)+'\n```\n\n人工评分：待评。'
    p.with_suffix('.md').write_text(text)
review=json.loads(Path('rag/eval/reports/langgraph_v1_schema_followup.json').read_text())
original=json.loads(Path('rag/eval/reports/langgraph_v1_schema_followup_unreviewed.json').read_text())
assert [c['response'] for c in review['challenge']]==[c['response'] for c in original['challenge']]
assert review['human_review_summary']['including_user_attribution_marker_fail']==4
base=Path('rag/eval/candidates/answer_evidence_v2');base.mkdir(parents=True,exist_ok=False)
files=list(protected)+['rag/service/answer_service.py','rag/service/answer_evidence_guards.py','rag/service/ask_graph.py','rag/service/mixed_service.py','rag/eval/test_answer_evidence_guards.py','rag/eval/test_ask_graph.py','rag/eval/test_mixed_service.py','rag/eval/verify_mixed_live.py','rag/eval/verify_graph_live.py','docs/ANSWER_EVIDENCE_FIX_2026-10-12.md']+reports+['rag/eval/reports/langgraph_v1_schema_followup.json','rag/eval/reports/langgraph_v1_schema_followup_unreviewed.json']
checksums={}
for f in files:
    d=base/f;d.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(f,d);checksums[f]=hashlib.sha256(d.read_bytes()).hexdigest()
manifest={'status':'pending_user_review_not_frozen_as_accepted','files':checksums,'tests_passed':64,'scope_refinement_targeted_tests_passed':11,
    'old_user_review':review['human_review_summary'],'new_answer_human_review':'pending',
    'protected_router_sql_entry_search_unchanged':True,'prompt_changed_for_evidence_handling':True,'no_secrets_archived':True}
(base/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
print('Verified route/SQL/search/entry unchanged; old reviewed answer payloads preserved; new candidate not accepted')
print(json.dumps({'candidate':str(base),'files':len(files),'tests':64},ensure_ascii=False))
PY
